def index(request):
    return render(request, "game/index.html")          # no context

template: drop {{ puzzle|json_script }} and {{ solution|json_script }}
template: ensure <meta name="viewport" content="width=device-width, initial-scale=1">

tests:
  assert "puzzle-data" not in response.content
  patch generator.generate_puzzle -> assert not called during index
  assert set(json.loads(new_puzzle_response)) == {"puzzle", "solution"}

resolveVisibility(setting, coarseQuery):
    show -> visible; hide -> collapsed with handle; auto -> coarseQuery.matches

onDigitTap(d):  activeDigit = (activeDigit == d) ? null : d
onCellTap(i):
    if givens[i] != 0: return
    if candidateSticky and activeDigit: store.toggleCandidate(i, activeDigit)
    else if activeDigit:                store.setValue(i, activeDigit)
    else:                               store.select(i)
onPencilTap(): candidateSticky = !candidateSticky; announce once
onCellLongPress(i, 400ms): openNoteEditor("cell", i)      // accelerator only

async function bootstrap():
    renderInertSkeleton()
    urlState = hash ? codec.decode(hash) : null
    local    = persistence.restore()
    adopted  = resolveConflict(urlState, local)          // CR1..CR5, evaluated once
    if adopted: render(adopted)
    else:       adopted = await createNewSession()
    if adopted: enableAdapters(); if consumedFragment: history.replaceState(cleanUrl)

async function createNewSession():
    if navigator.onLine == false: return showRetryPanel("offline")
    for attempt in 1..2:
        try:
            res = await fetch("/api/new-puzzle/", {signal: timeout(10_000)})
            if res.status >= 500: throw RetryableError
            if not res.ok: return showRetryPanel("server")     // 4xx, no retry
            return sessionFromPuzzle(await res.json())         // solution not stored
        catch RetryableError or AbortError:
            if attempt == 1: await delay(1000); continue
    return showRetryPanel("network")

showRetryPanel(cause):
    keep board inert; render panel outside the board
    focus the 48px retry button; return null
